def split_top(s):
    out=[]; cur=[]; depth=0; quote=None; i=0
    while i<len(s):
        c=s[i]
        if quote:
            cur.append(c)
            if c==quote and (i==0 or s[i-1]!="\\"): quote=None
        else:
            if c in "'\"": quote=c; cur.append(c)
            elif c in "[({": depth+=1; cur.append(c)
            elif c in "])}": depth-=1; cur.append(c)
            elif c=="," and depth==0: out.append("".join(cur).strip()); cur=[]
            else: cur.append(c)
        i+=1
    out.append("".join(cur).strip())
    return out

def py_eval_array(s):
    s=s.strip()
    if not s: return []
    try:
        return ast.literal_eval(s.replace("null","None").replace("true","True").replace("false","False"))
    except Exception:
        # Support unquoted CSV strings
        if s.startswith("[") and s.endswith("]"):
            inner=s[1:-1].strip()
            if not inner: return []
            return [x.strip().strip("'\"") for x in split_top(inner)]
        return [x.strip().strip("'\"") for x in split_top(s)]

def parse_tree(s):
    vals=py_eval_array(s)
    if not vals: return None
    class TreeNode:
        def __init__(self,val=0,left=None,right=None): self.val,self.left,self.right=val,left,right
    root=TreeNode(vals[0]); q=[root]; i=1
    while q and i<len(vals):
        u=q.pop(0)
        if i<len(vals) and vals[i] is not None: u.left=TreeNode(vals[i]); q.append(u.left)
        i+=1
        if i<len(vals) and vals[i] is not None: u.right=TreeNode(vals[i]); q.append(u.right)
        i+=1
    return root

def parse_list(s):
    class ListNode:
        def __init__(self,val=0,next=None): self.val,self.next=val,next
    s=s.strip()
    if "->" in s:
        vals=[x.strip() for x in s.split("->") if x.strip() and x.strip()!="null"]
    else:
        vals=py_eval_array(s)
    head=cur=None
    for x in vals:
        node=ListNode(int(x))
        if head is None: head=node
        else: cur.next=node
        cur=node
    return head

