class Solution:
    def pm009_isReachable(self, adj: list[list[int]], s: int, t: int) -> bool:
        from collections import deque
        vis={s}; q=deque([s])
        while q:
            u=q.popleft()
            if u==t: return True
            for v in adj[u]:
                if v not in vis: vis.add(v); q.append(v)
        return False

