class Solution:
    def pm017_firstAtLeast(self, a: list[int], x: int) -> int:
        l,r=0,len(a)
        while l<r:
            m=(l+r)//2
            if a[m]>=x: r=m
            else: l=m+1
        return l if l<len(a) else -1

