class Solution {
public:
    vector<int> pm024_topKValues(vector<int>& a, int k) { priority_queue<int,vector<int>,greater<int>> pq; for(int x:a){pq.push(x); if(pq.size()>k)pq.pop();} vector<int> o; while(!pq.empty()){o.push_back(pq.top());pq.pop();} sort(o.rbegin(),o.rend()); return o; }
};

