class Solution:
    def pm045_topKValues(self, a: list[int], k: int) -> list[int]:
        import heapq
        pq=[]
        for x in a:
            heapq.heappush(pq,x)
            if len(pq)>k: heapq.heappop(pq)
        return sorted(pq, reverse=True)

