class Solution:
    def pm054_processMinStack(self, ops: list[str]) -> list[int]:
        st=[]; mn=[]; out=[]
        for op in ops:
            if op.startswith('push '):
                x=int(op[5:]); st.append(x); mn.append(x if not mn else min(x,mn[-1]))
            elif op=='pop': st.pop(); mn.pop()
            else: out.append(mn[-1])
        return out

