class Solution:
    def pm058_closestPairSum(self, a: list[int], target: int) -> list[int]:
        l,r=0,len(a)-1; b1,b2=l,r; best=10**30
        while l<r:
            s=a[l]+a[r]; d=abs(s-target)
            if d<best: best=d; b1,b2=l,r
            if s<target: l+=1
            else: r-=1
        return [b1,b2]

