public:
    int pm059_longestAtMostBudget(vector<int>& a, int budget) { long long sum=0; int l=0,best=0; for(int r=0;r<(int)a.size();++r){sum+=a[r]; while(l<=r&&sum>budget) sum-=a[l++]; best=max(best,r-l+1);} return best; }
};

