class Solution:
    def pm059_longestAtMostBudget(self, a: list[int], budget: int) -> int:
        s=l=best=0
        for r,x in enumerate(a):
            s+=x
            while l<=r and s>budget:
                s-=a[l]; l+=1
            best=max(best,r-l+1)
        return best

