class Solution:
    def pm068_findTelemetryPair(self, a: list[int], target: int) -> list[int]:
        pos={}
        for i,x in enumerate(a):
            need=target-x
            if need in pos: return [pos[need], i]
            pos[x]=i
        return [-1,-1]

