class Solution:
    def pm071_countComponents(self, n: int, edges: list[list[int]]) -> int:
        from collections import deque
        g=[[] for _ in range(n)]
        for u,v in edges: g[u].append(v); g[v].append(u)
        vis=[0]*n; ans=0
        for i in range(n):
            if vis[i]: continue
            ans+=1; vis[i]=1; q=deque([i])
            while q:
                u=q.popleft()
                for v in g[u]:
                    if not vis[v]: vis[v]=1; q.append(v)
        return ans

