class Solution {
public:
    long long pm079_maxFixedWindowSum(vector<int>& a, int k) { long long cur=0; for(int i=0;i<k;++i) cur+=a[i]; long long best=cur; for(int i=k;i<(int)a.size();++i){cur+=a[i]-a[i-k]; best=max(best,cur);} return best; }
};

solution.reference_solution_python:
class Solution:
    def pm079_maxFixedWindowSum(self, a: list[int], k: int) -> int:
        cur=sum(a[:k]); best=cur
        for i in range(k,len(a)):
            cur += a[i]-a[i-k]
            best=max(best,cur)
        return best

