class Solution:
    def pm082_prefixExists(self, words: list[str], qs: list[str]) -> list[int]:
        trie={}
        for w in words:
            node=trie
            for ch in w: node=node.setdefault(ch,{})
        out=[]
        for q in qs:
            node=trie; ok=True
            for ch in q:
                if ch not in node: ok=False; break
                node=node[ch]
            out.append(1 if ok else 0)
        return out

