class Solution:
    def pm088_stableMergeSort(self, a: list[int]) -> list[int]:
        if len(a)<=1: return a
        m=len(a)//2
        l=self.pm088_stableMergeSort(a[:m]); r=self.pm088_stableMergeSort(a[m:]); o=[]; i=j=0
        while i<len(l) and j<len(r):
            if l[i]<=r[j]: o.append(l[i]); i+=1
            else: o.append(r[j]); j+=1
        o.extend(l[i:]); o.extend(r[j:]); return o

