class Solution:
    def pm091_lisLength(self, a: list[int]) -> int:
        import bisect
        d=[]
        for x in a:
            i=bisect.bisect_left(d,x)
            if i==len(d):d.append(x)
            else:d[i]=x
        return len(d)

