class Solution:
    def pm100_maxNonOverlap(self, jobs: list[list[int]]) -> int:
        jobs=sorted(jobs,key=lambda p:(p[1],p[0])); last=-10**18; ans=0
        for s,e in jobs:
            if s>=last: ans+=1; last=e
        return ans

