class Solution:
    def pm108_mergeWindows(self, a: list[list[int]]) -> list[list[int]]:
        if not a:return []
        a=sorted(a); o=[a[0][:]]
        for s,e in a[1:]:
            if s>o[-1][1]: o.append([s,e])
            else:o[-1][1]=max(o[-1][1],e)
        return o

