class Solution:
    def pm111_minLatency(self, n: int, g: list[list[tuple[int,int]]], s: int) -> list[int]:
        import heapq
        d=[10**18]*n; d[s]=0; pq=[(0,s)]
        while pq:
            du,u=heapq.heappop(pq)
            if du!=d[u]: continue
            for v,w in g[u]:
                nd=du+w
                if nd<d[v]: d[v]=nd; heapq.heappush(pq,(nd,v))
        return d

