class Solution:
    def pm112_levelOrder(self, adj: list[list[int]], start: int) -> list[list[int]]:
        from collections import deque
        n=len(adj); d=[-1]*n; d[start]=0; q=deque([start]); out=[]
        while q:
            cur=[]
            for _ in range(len(q)):
                u=q.popleft(); cur.append(u)
                for v in adj[u]:
                    if d[v]==-1: d[v]=d[u]+1; q.append(v)
            out.append(cur)
        return out

