class Solution:
    def pm127_minCoins(self, coins: list[int], amount: int) -> int:
        INF=10**9; dp=[INF]*(amount+1); dp[0]=0
        for x in range(1,amount+1):
            for c in coins:
                if c<=x: dp[x]=min(dp[x],dp[x-c]+1)
        return -1 if dp[amount]>=INF else dp[amount]

