class Solution:
    def pm146_maxFixedWindowSum(self, a: list[int], k: int) -> int:
        cur=sum(a[:k]); best=cur
        for i in range(k,len(a)):
            cur += a[i]-a[i-k]
            best=max(best,cur)
        return best

