class Solution:
    def pm158_minClimbCost(self, cost: list[int]) -> int:
        n=len(cost)
        if n<=1:return 0
        a=b=0
        for i in range(2,n+1):
            a,b=b,min(b+cost[i-1],a+cost[i-2])
        return b

