    def pm166_permutations(self, a: list[int]) -> list[list[int]]:
        out=[]
        def dfs(i):
            if i==len(a): out.append(a.copy()); return
            for j in range(i,len(a)):
                a[i],a[j]=a[j],a[i]; dfs(i+1); a[i],a[j]=a[j],a[i]
        dfs(0); return out

