public:
    int pm177_firstAtLeast(vector<int>& a, int x) { int l=0,r=a.size(); while(l<r){int m=l+(r-l)/2; if(a[m]>=x) r=m; else l=m+1;} return l<(int)a.size()?l:-1; }
};

