class Solution {
public:
    vector<int> pm178_findTelemetryPair(vector<int>& a, int target) { unordered_map<int,int> pos; for(int i=0;i<(int)a.size();++i){int need=target-a[i]; if(pos.count(need)) return {pos[need],i}; pos[a[i]]=i;} return {-1,-1}; }
};

