class Solution {
public:
    vector<int> pm180_topKValues(vector<int>& a, int k) { priority_queue<int,vector<int>,greater<int>> pq; for(int x:a){pq.push(x); if(pq.size()>k)pq.pop();} vector<int> o; while(!pq.empty()){o.push_back(pq.top());pq.pop();} sort(o.rbegin(),o.rend()); return o; }
};

solution.reference_solution_python:
class Solution:
    def pm180_topKValues(self, a: list[int], k: int) -> list[int]:
        import heapq
        pq=[]
        for x in a:
            heapq.heappush(pq,x)
            if len(pq)>k: heapq.heappop(pq)
        return sorted(pq, reverse=True)

