class Solution:
    def pm190_lcsLength(self, a: str, b: str) -> int:
        m=len(b); dp=[0]*(m+1)
        for i in range(1,len(a)+1):
            prev=0
            for j in range(1,m+1):
                old=dp[j]
                if a[i-1]==b[j-1]: dp[j]=prev+1
                else: dp[j]=max(dp[j],dp[j-1])
                prev=old
        return dp[m]

