class Solution:
    def pm194_countGridPaths(self, blocked: list[list[int]]) -> int:
        n,m=len(blocked),len(blocked[0]); dp=[0]*m; dp[0]=0 if blocked[0][0] else 1
        for i in range(n):
            for j in range(m):
                if blocked[i][j]: dp[j]=0
                elif j>0: dp[j]+=dp[j-1]
        return dp[-1]

