class Solution:
    def pm196_findRedundantEdge(self, n: int, edges: list[list[int]]) -> list[int]:
        p=list(range(n+1))
        def f(x):
            while p[x]!=x: p[x]=p[p[x]]; x=p[x]
            return x
        for u,v in edges:
            a,b=f(u),f(v)
            if a==b: return [u,v]
            p[a]=b
        return []

