class Solution:
    def pm197_nextGreater(self, a: list[int]) -> list[int]:
        o=[-1]*len(a); st=[]
        for i,x in enumerate(a):
            while st and a[st[-1]]<x:
                o[st.pop()]=x
            st.append(i)
        return o

